import{_ as a,o,c as l,a0 as i}from"./chunks/framework.CShDTZbC.js";const h=JSON.parse('{"title":"第 20 章 · AI 生成代码验货指南 ⭐","description":"","frontmatter":{},"headers":[],"relativePath":"book/part3/ch20.md","filePath":"book/part3/ch20.md","lastUpdated":1788537144000}'),e={name:"book/part3/ch20.md"};function s(r,t,d,c,u,p){return o(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="第-20-章-·-ai-生成代码验货指南-⭐" tabindex="-1">第 20 章 · AI 生成代码验货指南 ⭐ <a class="header-anchor" href="#第-20-章-·-ai-生成代码验货指南-⭐" aria-label="Permalink to &quot;第 20 章 · AI 生成代码验货指南 ⭐&quot;">​</a></h1><div class="ob-meta"><span class="chip">第三篇 · 实战篇</span><span class="chip">⏱ 精读约 55 分钟</span><span class="chip hot">👑 全书王牌 · 🤖 AI 主线</span><span class="ob-wip">写作中</span></div><div class="tip custom-block"><p class="custom-block-title">🎯 学完这章你能</p><ul><li>用&quot;三道关卡&quot;系统验货 AI 生成的策略代码</li><li>识别 AI 在量化场景的四类高发幻觉</li><li>明白为什么&quot;回测年化 80%&quot;的 AI 产出最值得怀疑</li></ul></div><blockquote><p>2026 年，人人都能让 AI 一分钟生成一个&quot;年化 80%&quot;的策略。<strong>生成能力已经不值钱，验货能力才是新的护城河</strong>——这一章是 <a href="/book/part2/ch10.html">第 10 章</a> 八大坑在 AI 场景的全面升级。</p></blockquote><h2 id="_20-1-ai-量化代码的四类高发幻觉" tabindex="-1">20.1 AI 量化代码的四类高发幻觉 <a class="header-anchor" href="#_20-1-ai-量化代码的四类高发幻觉" aria-label="Permalink to &quot;20.1 AI 量化代码的四类高发幻觉&quot;">​</a></h2><table tabindex="0"><thead><tr><th>幻觉类型</th><th>症状</th><th>案例</th></tr></thead><tbody><tr><td>📅 时序幻觉</td><td>信号偷看未来（未来函数）</td><td>忘了 <code>shift(1)</code>；用当日收盘算当日信号</td></tr><tr><td>📚 API 幻觉</td><td>调用不存在的函数/参数</td><td>编造 <code>get_price_v2()</code>、参数名张冠李戴</td></tr><tr><td>📉 数据幻觉</td><td>编造历史行情、虚构统计规律</td><td>&quot;该策略在 2015 年股灾中逆势上涨 40%&quot;（查无此事）</td></tr><tr><td>🧮 逻辑幻觉</td><td>代码能跑但逻辑≠你的想法</td><td>你说&quot;突破 20 日高点买入&quot;，它写成了&quot;高于 20 日均线&quot;</td></tr></tbody></table><h2 id="_20-2-三道验货关卡" tabindex="-1">20.2 三道验货关卡 <a class="header-anchor" href="#_20-2-三道验货关卡" aria-label="Permalink to &quot;20.2 三道验货关卡&quot;">​</a></h2><p><strong>第一关：机器检查（自动）</strong></p><ul><li>静态扫描：未来函数模式（信号未 shift、用了 <code>shift(-n)</code>）、除零、空值传播</li><li>API 核对：每个函数调用对照平台文档（让 AI 自己对照也行，但要抽查）</li><li>成本假设：手续费/滑点设了没有</li></ul><p><strong>第二关：数据检查（半自动）</strong></p><ul><li>分年度收益拆解：是不是只赚了某一段？</li><li>参数敏感性：动一个参数结果剧变 = 过拟合警报</li><li>与基准对比：跑不赢&quot;一直拿着&quot;，图什么？</li></ul><p><strong>第三关：人工审查（必须人做）</strong></p><ul><li>逐行讲给自己听：AI 能跑 ≠ 你能懂</li><li>逻辑对照&quot;策略逻辑说明书&quot;：它写的是你想的吗？</li><li>常识拷问：这个策略赚的钱，是谁亏的？对手盘理性吗？</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 人话翻译</p><p>验货流程的本质：<strong>机器管重复，数据管诚实，人管常识。</strong> 三关全过，才配叫&quot;完成&quot;。</p></div><h2 id="_20-3-实战-验一个-ai-生成的策略-写作中" tabindex="-1">20.3 实战：验一个 AI 生成的策略（写作中） <a class="header-anchor" href="#_20-3-实战-验一个-ai-生成的策略-写作中" aria-label="Permalink to &quot;20.3 实战：验一个 AI 生成的策略（写作中）&quot;">​</a></h2><p>完整演示：让 AI 生成一个&quot;网红策略&quot;→ 三道关卡逐一体检 → 揪出 3 个坑 → 修复前后回测对比。</p><h2 id="_20-4-与体检站的关系" tabindex="-1">20.4 与体检站的关系 <a class="header-anchor" href="#_20-4-与体检站的关系" aria-label="Permalink to &quot;20.4 与体检站的关系&quot;">​</a></h2><p>本章的清单就是&quot;策略体检站&quot;工具（规划中）的规则库说明书——纸质版教你自己查，在线版帮你机器查。</p><div class="info custom-block"><p class="custom-block-title">📋 自查清单（预告）</p><ul><li>[ ] 我有固定的验货流程，不靠&quot;看起来挺对&quot;</li><li>[ ] 我能让 AI 解释它代码的每一行，并对照文档抽查过 API</li><li>[ ] 我对&quot;回测特别好&quot;的产出，怀疑程度高于&quot;回测一般&quot;的</li></ul></div><p>→ 下一篇：<a href="/book/part4/">第四篇 · AI 协作篇</a>——把 AI 搭档用到极致。</p>',20)])])}const q=a(e,[["render",s]]);export{h as __pageData,q as default};
